let svcMe=null,svcWorkspace=null,svcCategories=[],svcProvider=null,svcProviderBlock=false,svcMode='directory',svcProviderSection='Profile';
const stok=()=>window.ABLSession?.authenticated()?'cookie-session':'';
const sh=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const sphp=v=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(v)||0);
const snice=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const SERVICE_PRICE_METHOD_LABELS={quotation:'Quote after details',fixed:'Fixed price',hourly:'Hourly rate',half_day:'Half-day rate',daily:'Daily rate',per_unit:'Per unit',per_sqm:'Per m²',inspection_then_quote:'Inspection, then quote'};
const SERVICE_UNIT_LABELS={job:'job',hour:'hour',half_day:'half-day',day:'day',sqm:'m²',item:'item',unit:'unit',visit:'visit'};
const SERVICE_MATERIALS_LABELS={included:'Materials included',separate:'Materials priced separately',customer_supplied:'Customer supplies materials',mixed:'Materials arrangement varies'};
const SERVICE_MODE_LABELS={at_customer:'At customer address',workshop:'At provider workshop',both:'Customer address or workshop'};
function servicePriceSummary(offer={}){const method=SERVICE_PRICE_METHOD_LABELS[offer.pricing_method]||'Quote after details',unit=SERVICE_UNIT_LABELS[offer.rate_unit]||'job';let price='';if(offer.price_from!=null&&offer.price_to!=null)price=`${sphp(offer.price_from)}–${sphp(offer.price_to)} / ${unit}`;else if(offer.price_from!=null)price=`From ${sphp(offer.price_from)} / ${unit}`;else if(offer.price_to!=null)price=`Up to ${sphp(offer.price_to)} / ${unit}`;return[method,price,offer.minimum_charge!=null?`Minimum ${sphp(offer.minimum_charge)}`:'',offer.callout_fee!=null?`Call-out ${sphp(offer.callout_fee)}`:''].filter(Boolean)}
function serviceOfferCard(offer={}){const summary=servicePriceSummary(offer);return `<article class="serviceOfferCard"><div><strong>${sh(offer.service_label||offer.name||'Service')}</strong><span>${sh(summary[0]||'Quote after details')}</span></div>${summary.slice(1).length?`<div class="serviceOfferPrices">${summary.slice(1).map(value=>`<span>${sh(value)}</span>`).join('')}</div>`:''}<div class="serviceOfferMeta"><span>${sh(SERVICE_MATERIALS_LABELS[offer.materials_policy]||SERVICE_MATERIALS_LABELS.separate)}</span><span>${sh(SERVICE_MODE_LABELS[offer.service_mode]||SERVICE_MODE_LABELS.at_customer)}</span></div>${offer.pricing_note?`<p>${sh(offer.pricing_note)}</p>`:''}</article>`}
async function sapi(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};const r=await fetch(path,{...options,headers});const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.error||`Request failed (${r.status})`);return b}
function stoast(msg){let t=document.getElementById('roleToast')||document.getElementById('servicesFallbackToast');if(!t){t=document.createElement('div');t.id='servicesFallbackToast';t.className='roleToast';t.setAttribute('role','status');t.setAttribute('aria-live','polite');document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function ensureSvc(){const shell=document.getElementById('shell');if(!shell)return false;if(!document.getElementById('servicesWorkspace')){svcWorkspace=document.createElement('section');svcWorkspace.id='servicesWorkspace';svcWorkspace.className='servicesWorkspace hidden';shell.querySelector('.topbar')?.insertAdjacentElement('afterend',svcWorkspace)}else svcWorkspace=document.getElementById('servicesWorkspace');if(!document.getElementById('serviceModalBackdrop')){const m=document.createElement('div');m.id='serviceModalBackdrop';m.className='serviceModalBackdrop hidden';m.innerHTML='<section id="serviceModal" class="serviceModal"></section>';document.body.appendChild(m);m.onclick=e=>{if(e.target===m)closeServiceModal()}}return true}
function hideSvcBase(){document.querySelectorAll('#shell > .view').forEach(v=>v.classList.add('hidden'));document.querySelector('.bottomNav')?.classList.add('hidden');for(const id of ['roleHub','accountSettingsWorkspace','ordersWorkspace','marketWorkspace','supWorkspace','deliveryWorkspace','profileMoneyWorkspace','profileSettingsWorkspace'])document.getElementById(id)?.classList.add('hidden');for(const id of ['basketBar','orderModalBackdrop','checkoutBackdrop','serviceModalBackdrop','supModalBg','deliveryModalBg'])document.getElementById(id)?.classList.add('hidden');document.getElementById('serviceModal')?.replaceChildren();document.body.style.overflow=''}
function openServicesWorkspace(){if(!ensureSvc())return false;if(window.BusinessLifeShell?.openFeatureWorkspace?.('servicesWorkspace'))return true;hideSvcBase();svcWorkspace.classList.remove('hidden');return true}
function closeSvc(){closeServiceModal();svcWorkspace?.classList.add('hidden');window.BusinessLifeShell?.showActiveWorkspace?.()}
function svcHeader(title,sub,extra=''){return `<div class="servicesHeader"><button class="servicesBack" type="button" data-svc-back>‹</button><div class="servicesHeaderCopy"><h1>${sh(title)}</h1><p>${sh(sub)}</p></div>${extra}</div>`}
function bindSvcBack(fn=closeSvc){const b=svcWorkspace.querySelector('[data-svc-back]');if(b)b.onclick=fn}
function photo(p){return p?.profile_image_data_url?`<span class="providerPhoto"><img src="${p.profile_image_data_url}" alt=""></span>`:`<span class="providerPhoto">${sh((p?.display_name||'S')[0]?.toUpperCase()||'S')}</span>`}
function openServiceModal(){document.getElementById('serviceModalBackdrop')?.classList.remove('hidden');document.body.style.overflow='hidden'}
function closeServiceModal(){document.getElementById('serviceModalBackdrop')?.classList.add('hidden');document.body.style.overflow='';document.getElementById('serviceModal')?.replaceChildren()}
function fileData(file,max=1_400_000){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(file.size>max)return reject(new Error('File is too large for this preview.'));const r=new FileReader();r.onerror=()=>reject(new Error('Could not read file'));r.onload=()=>resolve(String(r.result||''));r.readAsDataURL(file)})}
function imageData(file,size=640){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(!['image/png','image/jpeg','image/webp'].includes(file.type))return reject(new Error('Choose PNG, JPEG or WebP'));const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');const scale=Math.min(1,size/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/webp',.82))};img.onerror=()=>reject(new Error('Invalid image'));img.src=r.result};r.readAsDataURL(file)})}

async function loadCategories(){if(!svcCategories.length)svcCategories=await sapi('/api/services/categories');return svcCategories}
async function openDirectory(category=''){if(!openServicesWorkspace())return;svcMode='directory';await loadCategories();await renderDirectory(category)}
async function renderDirectory(category=''){svcWorkspace.innerHTML=svcHeader('Local Services','Find trusted skills near you',`<button class="marketFilter" id="myServiceJobs" type="button">My requests</button>`)+`<section class="servicesHero"><span>Business & Life • local skills</span><h2>People you can know. Work you can verify.</h2><p>Compare services, experience, verified qualifications and feedback from completed jobs — then request a quote inside the app.</p></section><div class="serviceFilterRow"><button class="serviceFilter ${!category?'active':''}" data-svc-filter="">All</button>${svcCategories.map(c=>`<button class="serviceFilter ${category===c.code?'active':''}" data-svc-filter="${sh(c.code)}">${sh(c.name)}</button>`).join('')}</div><div id="providerGrid" class="providerGrid"><div class="servicesEmpty">Loading providers…</div></div>`;bindSvcBack();document.getElementById('myServiceJobs').onclick=openCustomerJobs;svcWorkspace.querySelectorAll('[data-svc-filter]').forEach(b=>b.onclick=()=>renderDirectory(b.dataset.svcFilter));try{const list=await sapi(`/api/services/providers${category?`?category=${encodeURIComponent(category)}`:''}`);const host=document.getElementById('providerGrid');host.innerHTML=list.length?list.map(providerCard).join(''):'<div class="servicesEmpty">No public Service Providers match this category yet.</div>';host.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>openProvider(Number(b.dataset.provider)))}catch(e){document.getElementById('providerGrid').innerHTML=`<div class="servicesEmpty">${sh(e.message)}</div>`}}
function providerCard(p){const verified=(p.verified_credentials||[]).length;return `<button class="providerCard" type="button" data-provider="${p.account_id}">${photo(p)}<span class="providerCopy"><strong>${sh(p.display_name)}</strong><span class="headline">${sh(p.professional_headline||'Local Service Provider')}</span><span class="providerMeta">${(p.services||[]).slice(0,2).map(s=>`<span>${sh(s.name)}</span>`).join('')}${verified?`<span class="verified">✓ ${verified} verified</span>`:''}${p.rating!=null?`<span class="rating">★ ${p.rating} (${p.review_count})</span>`:''}${p.years_experience!=null?`<span>${Number(p.years_experience)}y exp.</span>`:''}</span></span><span class="providerOpen">›</span></button>`}
async function openProvider(id){try{const[provider,blockState]=await Promise.all([sapi(`/api/services/providers/${id}`),sapi(`/api/user-blocks/${id}/status`)]);svcProvider=provider;svcProviderBlock=Boolean(blockState.blocked_by_me);renderProvider()}catch(e){stoast(e.message)}}
async function openProviderReport(provider){const loader=window.BusinessLifeFeatureLoader;if(!loader?.openSafetyReport)return stoast('Safety reporting is not available yet.');try{await loader.openSafetyReport({related_type:'service_provider',related_id:Number(provider.account_id),display_label:`Service Provider: ${provider.display_name}`,suggested_category:'Safety / abuse'})}catch{}}
function openProviderBlock(provider){const active=Boolean(svcProviderBlock),m=document.getElementById('serviceModal');if(active){m.innerHTML=`<h2>Unblock ${sh(provider.display_name)}?</h2><p class="blockSafetyCopy">Unblocking allows new Local Services requests. Existing jobs, payments, reports and history are not changed.</p><div id="blockMsg" class="fileNote"></div><div class="serviceModalActions"><button class="cancel" type="button">Cancel</button><button class="save" id="confirmUnblock" type="button">Unblock</button></div>`;openServiceModal();m.querySelector('.cancel').onclick=closeServiceModal;m.querySelector('#confirmUnblock').onclick=async()=>{try{await sapi(`/api/user-blocks/${provider.account_id}`,{method:'DELETE'});closeServiceModal();svcProviderBlock=false;renderProvider();stoast('Local Services block removed.')}catch(err){document.getElementById('blockMsg').textContent=err.message}};return}m.innerHTML=`<h2>Block ${sh(provider.display_name)}?</h2><form id="providerBlockForm" class="serviceModalForm"><p class="blockSafetyCopy">This prevents new Local Services requests between your accounts. It does not cancel active jobs, hide transaction history or submit a report.</p><label>Private reason<select id="providerBlockReason"><option value="safety">Safety concern</option><option value="harassment">Harassment</option><option value="privacy">Privacy concern</option><option value="fraud_concern">Fraud concern</option><option value="unwanted_contact">Unwanted contact</option><option value="other">Other</option></select></label><small class="blockSafetyCopy">The other account is not shown this reason.</small><div id="blockMsg" class="fileNote"></div><div class="serviceModalActions"><button class="cancel" type="button">Cancel</button><button class="save serviceBlockConfirm">Block on Local Services</button></div></form>`;openServiceModal();m.querySelector('.cancel').onclick=closeServiceModal;m.querySelector('#providerBlockForm').onsubmit=async e=>{e.preventDefault();try{await sapi('/api/user-blocks',{method:'POST',body:JSON.stringify({blocked_account_id:Number(provider.account_id),reason_category:document.getElementById('providerBlockReason').value})});closeServiceModal();svcProviderBlock=true;renderProvider();stoast('New Local Services requests are blocked.')}catch(err){document.getElementById('blockMsg').textContent=err.message}}}
function renderProvider(){
  const p=svcProvider,blocked=Boolean(svcProviderBlock),services=Array.isArray(p.services)?p.services:[];
  svcWorkspace.innerHTML=svcHeader(p.display_name,p.professional_headline||'Service Provider')+`<div data-bl-pricing="local_services"></div>
    <section class="providerProfileHero">${photo(p)}<div class="providerProfileCopy"><h2>${sh(p.display_name)}</h2><p>${sh(p.professional_headline||'Local Service Provider')}</p><div class="providerMeta">${p.rating!=null?`<span class="rating">★ ${p.rating} • ${p.review_count} reviews</span>`:''}${p.years_experience!=null?`<span>${Number(p.years_experience)} years experience</span>`:''}${p.same_day_available?'<span class="verified">Same-day available</span>':''}</div></div></section>
    <div class="providerSafetyBar"><div class="providerSafetyActions"><button class="serviceSafetyAction" id="reportProvider" type="button">Report provider</button><button class="serviceBlockAction ${blocked?'active':''}" id="blockProvider" type="button">${blocked?'Unblock provider':'Block provider'}</button></div><span>${blocked?'Local Services block active · private setting':'Private safety controls · report is separate'}</span></div>
    <section class="providerSection"><h3>About</h3><p class="serviceBodyCopy">${sh(p.about||'No public description yet.')}</p>${p.service_area?`<div class="providerMeta"><span>📍 ${sh(p.service_area)}</span>${p.languages?`<span>🗣 ${sh(p.languages)}</span>`:''}</div>`:''}</section>
    <section class="providerSection"><h3>Services & guide prices</h3><p class="serviceGuideNotice">Guide prices describe how this provider usually charges. Your exact, itemised quote must be accepted before work starts.</p><div class="serviceOfferList">${services.length?services.map(serviceOfferCard).join(''):'<div class="servicesEmpty">No services listed</div>'}</div></section>
    <section class="providerSection"><h3>Qualifications & evidence</h3>${p.credentials.length?p.credentials.map(c=>`<div class="credentialRow"><span class="credentialIcon">🎓</span><span class="credentialCopy"><strong>${sh(c.title)}</strong><small>${sh(c.issuing_body||snice(c.credential_type))}</small></span><span class="credentialBadge ${c.verification_status==='verified'?'verified':''}">${c.verification_status==='verified'?'✓ Verified':sh(snice(c.verification_status))}</span></div>`).join(''):'<div class="servicesEmpty">No qualification evidence is publicly listed. Check experience and portfolio.</div>'}</section>
    ${p.portfolio.length?`<section class="providerSection"><h3>Portfolio</h3><div class="portfolioGrid">${p.portfolio.map(i=>`<article class="portfolioItem"><img src="${i.image_data_url}" alt=""><div><strong>${sh(i.title)}</strong><p>${sh(i.description||i.category||'Work example')}</p></div></article>`).join('')}</div></section>`:''}
    <section class="providerSection"><h3>Availability</h3><div class="providerMeta">${p.availability_text?`<span>${sh(p.availability_text)}</span>`:'<span>Ask provider for availability</span>'}</div><button class="requestServiceBtn" id="requestService" type="button" ${blocked?'disabled':''}>${blocked?'New requests blocked':'Request this Service Provider'}</button>${blocked?'<p class="blockBoundary">Existing jobs, payments, reports, reviews and history remain available.</p>':''}</section>`;
  bindSvcBack(()=>renderDirectory());
  document.getElementById('reportProvider').onclick=()=>openProviderReport(p);
  document.getElementById('blockProvider').onclick=()=>openProviderBlock(p);
  if(!blocked)document.getElementById('requestService').onclick=openRequestModal;
}
function openRequestModal(){
  const p=svcProvider,m=document.getElementById('serviceModal');
  const opts=p.services.map(s=>`<option value="${sh(s.code)}" data-label="${sh(s.service_label||s.name)}">${sh(s.service_label||s.name)}</option>`).join('');
  const coarseArea=svcMe?.geography?.path_text||svcMe?.geography?.name||'Official area unavailable';
  m.innerHTML=`<h2>Request ${sh(p.display_name)}</h2><form id="requestServiceForm" class="serviceModalForm"><label>Service<select id="requestCategory">${opts}</select></label><div id="requestPriceGuide" class="requestPriceGuide"></div><label>What do you need?<textarea id="requestDescription" rows="4" required placeholder="Describe the work, dimensions, quantity and condition — without contact details"></textarea></label><div class="fileNote">Guide prices are not a final bill. The provider must send an itemised quote and you must accept that exact version before work starts.</div><label>Area shown before quote acceptance<input id="requestArea" value="${sh(coarseArea)}" readonly></label><label>Exact service address<input id="requestLocation" value="${sh(svcMe?.account?.address||'')}" required placeholder="House/unit, street and access details"></label><div class="fileNote">The Service Provider sees only your official area before you accept a quote. The exact address is released only while the accepted job is active; each access is logged.</div><label>Preferred time / window<input id="requestWindow" placeholder="e.g. Saturday morning"></label><div id="serviceModalMsg" class="fileNote"></div><div class="serviceModalActions"><button class="cancel" type="button">Cancel</button><button class="save">Send request</button></div></form>`;
  openServiceModal();
  const serviceSelect=m.querySelector('#requestCategory'),renderGuide=()=>{const offer=p.services[serviceSelect.selectedIndex]||{};m.querySelector('#requestPriceGuide').innerHTML=serviceOfferCard(offer)};
  serviceSelect.onchange=renderGuide;renderGuide();
  m.querySelector('.cancel').onclick=closeServiceModal;
  m.querySelector('#requestServiceForm').onsubmit=async e=>{
    e.preventDefault();
    const sel=document.getElementById('requestCategory'),service=p.services[sel.selectedIndex],cat=svcCategories.find(c=>c.code===service?.code);
    try{
      await sapi('/api/services/jobs',{method:'POST',body:JSON.stringify({
        provider_account_id:p.account_id,category_id:cat?.id,service_label:service?.service_label||service?.name,
        description:document.getElementById('requestDescription').value,
        coarse_location:document.getElementById('requestArea').value,
        service_location:document.getElementById('requestLocation').value,
        requested_window:document.getElementById('requestWindow').value
      })});
      closeServiceModal();stoast('Service request sent. Your exact address remains private until quote acceptance.');await openCustomerJobs();
    }catch(err){document.getElementById('serviceModalMsg').textContent=err.message}
  };
}

async function enrichJobPayments(jobs){
  const list=Array.isArray(jobs)?jobs:[];
  const targets=list.filter(j=>j.status==='completed'&&j.customer_confirmed_at);
  if(!targets.length)return list;
  const summaries=new Map();
  let cursor=0;
  async function worker(){
    while(cursor<targets.length){
      const job=targets[cursor++];
      try{summaries.set(Number(job.id),await sapi('/api/payments/service-jobs/'+job.id+'/summary'))}
      catch{summaries.set(Number(job.id),null)}
    }
  }
  await Promise.all(Array.from({length:Math.min(6,targets.length)},()=>worker()));
  return list.map(job=>summaries.has(Number(job.id))?{...job,_payment:summaries.get(Number(job.id))}:job);
}
async function openCustomerJobs(){if(!openServicesWorkspace())return;const jobs=await sapi('/api/services/jobs/mine');const mine=jobs.filter(j=>Number(j.customer_account_id)===Number(svcMe.account.id));const enriched=await enrichJobPayments(mine);svcWorkspace.innerHTML=svcHeader('My Service Requests','Quotes, scheduled work and completed jobs')+`<div class="jobGrid">${enriched.length?enriched.map(j=>jobCard(j,'customer')).join(''):'<div class="servicesEmpty">You have not requested a service yet.</div>'}</div>`;bindSvcBack(()=>renderDirectory());bindJobActions('customer')}
const PROVIDER_SECTION_META={
  Profile:['Public Profile','Manage the information customers can see'],
  Services:['Services Offered','Choose the tasks customers can request'],
  Qualifications:['Qualifications & CV','Credentials, CV summary and work evidence'],
  Quotes:['Requests & Quotes','Review new requests and send quotations'],
  Jobs:['Jobs','Accepted, scheduled, active and completed work'],
  Reviews:['Reviews','Verified feedback from customer-confirmed jobs']
};
function providerQualificationPanel(data){const p=data.profile||{},portfolio=data.portfolio||[];return credentialsEditor(data)+`<section class="providerEditCard"><h2>CV & work evidence</h2><p>Your original CV stays private. This section shows the public-safe summary and portfolio state.</p><div class="providerMeta"><span>${sh(p.cv_public_summary||'No public CV summary yet.')}</span><span>${portfolio.length} portfolio item${portfolio.length===1?'':'s'}</span></div><button id="editProviderCv" type="button" style="margin-top:10px;border:0;border-radius:13px;padding:11px;background:#17233c;color:#fff;font-weight:900;width:100%">Edit CV & public summary</button></section>`}
function providerJobsPanel(jobs,section){const quoteStates=new Set(['requested','provider_reviewing','quoted']),jobStates=new Set(['accepted','scheduled','in_progress','completed','cancelled','disputed']);const selected=jobs.filter(j=>section==='Quotes'?quoteStates.has(j.status):jobStates.has(j.status));const title=section==='Quotes'?'Requests awaiting quote':'Your service jobs';const empty=section==='Quotes'?'No service requests are waiting for a quote.':'No accepted or active service jobs yet.';return `<section class="providerEditCard"><h2>${title}</h2><p>${section==='Quotes'?'New requests stay here while you review and quote them.':'Track accepted, scheduled, active and completed customer work.'}</p><div id="providerJobs" class="jobGrid">${selected.length?selected.map(j=>jobCard(j,'provider')).join(''):`<div class="servicesEmpty">${empty}</div>`}</div></section>`}
function providerReviewsPanel(data){const reviews=data.reviews||[];return `<section class="providerEditCard"><h2>Verified reviews</h2><p>Only published feedback linked to a customer-confirmed completed service job appears here.</p><div class="providerMeta"><span class="rating">★ ${data.rating==null?'No rating yet':sh(data.rating)} · ${Number(data.review_count||0)} review${Number(data.review_count||0)===1?'':'s'}</span></div><div class="jobGrid" style="margin-top:12px">${reviews.length?reviews.map(r=>`<article class="jobCard"><div class="jobCardTop"><strong>${sh(r.service_label||'Service job')}</strong><span class="jobStatus">★ ${sh(r.overall)}</span></div><p>${sh(r.review_text||'No written comment.')}</p><div class="providerMeta"><span>${sh(r.reviewer_name||'Customer')}</span><span>${new Date(r.created_at).toLocaleDateString()}</span></div></article>`).join(''):'<div class="servicesEmpty">No published verified reviews yet.</div>'}</div></section>`}
async function openProviderWorkspace(section='Profile'){const normalized=PROVIDER_SECTION_META[section]?section:'Profile';svcProviderSection=normalized;if(!openServicesWorkspace())return;await loadCategories();const data=await sapi('/api/service-provider/me');let body='';if(normalized==='Profile')body=profileEditor(data);else if(normalized==='Services')body=servicesEditor(data);else if(normalized==='Qualifications')body=providerQualificationPanel(data);else if(normalized==='Reviews')body=providerReviewsPanel(data);else{const jobs=await sapi('/api/services/jobs/mine');const mine=jobs.filter(j=>Number(j.provider_account_id)===Number(svcMe.account.id));const enriched=normalized==='Jobs'?await enrichJobPayments(mine):mine;body=providerJobsPanel(enriched,normalized)}const meta=PROVIDER_SECTION_META[normalized];svcWorkspace.innerHTML=svcHeader(meta[0],meta[1])+`<div data-bl-pricing="local_services"></div>`+body;bindSvcBack();bindProviderEditors(data);if(normalized==='Qualifications')document.getElementById('editProviderCv')?.addEventListener('click',()=>openProviderWorkspace('Profile'));if(['Quotes','Jobs'].includes(normalized))bindJobActions('provider')}
function profileEditor(data){const p=data.profile||{};const vis=svcMe.profiles.find(x=>x.role==='service_provider')?.visibility||'private';return `<section class="providerEditCard"><h2>Public service profile</h2><p>Your original CV and credential files stay private. Customers see only the public-safe information and verification status.</p><form id="providerProfileForm" class="providerEditForm"><label>Profile photo<input id="providerPhotoFile" type="file" accept="image/png,image/jpeg,image/webp"></label><label>Public/service name<input id="providerName" value="${sh(p.display_name||svcMe.account.display_name)}"></label><label>Professional headline<input id="providerHeadline" value="${sh(p.professional_headline||'')}" placeholder="e.g. Carpenter • Furniture repair"></label><label>About<textarea id="providerAbout" rows="4">${sh(p.about||'')}</textarea></label><label>Service area<input id="providerArea" value="${sh(p.service_area||'')}" placeholder="Barangay / city / radius description"></label><div class="merchantStoreForm two"><label>Years experience<input id="providerYears" type="number" min="0" step="0.5" value="${p.years_experience??''}"></label><label>Languages<input id="providerLanguages" value="${sh(p.languages||'')}"></label></div><label>Availability<input id="providerAvailability" value="${sh(p.availability_text||'')}" placeholder="Mon–Sat, 8:00–17:00"></label><div class="merchantStoreForm two"><label>Pricing<select id="providerPricing"><option value="quotation">Quotation required</option><option value="fixed">Fixed price</option><option value="hourly">Hourly</option><option value="daily">Daily</option><option value="mixed">Mixed</option></select></label><label>Visibility<select id="providerVisibility"><option value="private" ${vis==='private'?'selected':''}>Private</option><option value="relationship_only" ${vis==='relationship_only'?'selected':''}>Relationships only</option><option value="public" ${vis==='public'?'selected':''}>Public in Local Services</option></select></label></div><div class="merchantStoreForm two"><label>Price from ₱<input id="providerFrom" type="number" min="0" step="0.01" value="${p.price_from??''}"></label><label>Price to ₱<input id="providerTo" type="number" min="0" step="0.01" value="${p.price_to??''}"></label></div><label class="serviceCheck"><input id="providerSameDay" type="checkbox" ${p.same_day_available?'checked':''}> Same-day availability</label><label class="serviceCheck"><input id="providerReputation" type="checkbox" ${p.public_reputation_enabled?'checked':''}> Show verified reviews/rating publicly and participate in ranking</label><label>CV / resume PDF or image (private)<input id="providerCv" type="file" accept="application/pdf,image/png,image/jpeg,image/webp"></label><label>Public CV/experience summary<textarea id="providerCvSummary" rows="3" placeholder="Summarize experience without private contact data">${sh(p.cv_public_summary||'')}</textarea></label><div class="fileNote">Formal credential documents and your original CV are private evidence. Public customers see verified badges, public summary and work history — not the raw file.</div><button>Save profile</button><div id="providerProfileMsg" class="fileNote"></div></form></section>`}
function selectOptions(options,current){return Object.entries(options).map(([value,label])=>`<option value="${sh(value)}" ${value===current?'selected':''}>${sh(label)}</option>`).join('')}
function serviceOfferEditorCard(category,offer={}){
  const active=Boolean(offer.category_id),id=Number(category.id),method=offer.pricing_method||'quotation',unit=offer.rate_unit||'job';
  return `<article class="serviceOfferEditor" data-service-offer="${id}">
    <label class="serviceOfferToggle"><input type="checkbox" data-service-category="${id}" ${active?'checked':''}><span><strong>${sh(category.name)}${category.credential_gate?' 🔐':''}</strong><small>Set how this service is priced</small></span></label>
    <div class="serviceOfferFields ${active?'':'hidden'}" data-service-config>
      <label>Public service name<input data-service-field="service_label" value="${sh(offer.service_label||category.name)}" maxlength="120"></label>
      <div class="serviceFormGrid"><label>Pricing method<select data-service-field="pricing_method">${selectOptions(SERVICE_PRICE_METHOD_LABELS,method)}</select></label><label>Rate unit<select data-service-field="rate_unit">${selectOptions(SERVICE_UNIT_LABELS,unit)}</select></label></div>
      <div class="serviceFormGrid"><label>Guide price from ₱<input data-service-field="price_from" type="number" min="0" step="0.01" value="${offer.price_from??''}" placeholder="Optional"></label><label>Guide price to ₱<input data-service-field="price_to" type="number" min="0" step="0.01" value="${offer.price_to??''}" placeholder="Optional"></label></div>
      <div class="serviceFormGrid"><label>Minimum charge ₱<input data-service-field="minimum_charge" type="number" min="0" step="0.01" value="${offer.minimum_charge??''}" placeholder="Optional"></label><label>Call-out / inspection ₱<input data-service-field="callout_fee" type="number" min="0" step="0.01" value="${offer.callout_fee??''}" placeholder="Optional"></label></div>
      <div class="serviceFormGrid"><label>Materials<select data-service-field="materials_policy">${selectOptions(SERVICE_MATERIALS_LABELS,offer.materials_policy||'separate')}</select></label><label>Where you work<select data-service-field="service_mode">${selectOptions(SERVICE_MODE_LABELS,offer.service_mode||'at_customer')}</select></label></div>
      <label>Pricing note<textarea data-service-field="pricing_note" rows="2" maxlength="600" placeholder="Explain what the guide price covers and what is extra">${sh(offer.pricing_note||'')}</textarea></label>
    </div>
  </article>`;
}
function servicesEditor(data){
  const byCategory=new Map((data.services||[]).map(service=>[Number(service.category_id),service]));
  return `<section class="providerEditCard"><h2>Services & pricing</h2><p>Choose each service and publish a clear charging method. Ranges are optional guide prices; the job total is set only by an accepted itemised quote.</p><form id="providerServicesForm"><div class="serviceOfferEditorList">${svcCategories.map(category=>serviceOfferEditorCard(category,byCategory.get(Number(category.id)))).join('')}</div><div id="providerServicesMsg" class="fileNote"></div><button class="serviceEditorSave">Save services & pricing</button></form></section>`;
}
function credentialsEditor(data){return `<section class="providerEditCard"><h2>Qualifications & credentials</h2><p>PRC/TESDA/vocational/training/experience evidence is displayed with its real verification status.</p><div class="credentialListPrivate">${(data.credentials||[]).map(c=>`<div class="privateCredential"><strong>${sh(c.title)}</strong><small>${sh(snice(c.credential_type))} • ${sh(snice(c.verification_status))}${c.issuing_body?` • ${sh(c.issuing_body)}`:''}</small></div>`).join('')||'<div class="servicesEmpty">No credential evidence submitted yet.</div>'}</div><button id="addCredential" style="margin-top:10px;border:0;border-radius:13px;padding:11px;background:#17233c;color:#fff;font-weight:900;width:100%" type="button">+ Add qualification / evidence</button></section>`}
async function bindProviderEditors(data){
  const p=data.profile||{},profileForm=document.getElementById('providerProfileForm'),servicesForm=document.getElementById('providerServicesForm'),addCredential=document.getElementById('addCredential');
  if(profileForm){
    document.getElementById('providerPricing').value=p.pricing_model||'quotation';
    profileForm.onsubmit=async event=>{event.preventDefault();const msg=document.getElementById('providerProfileMsg');msg.textContent='Saving…';try{const photo=await imageData(document.getElementById('providerPhotoFile').files?.[0]);const cvFile=document.getElementById('providerCv').files?.[0];const cv=await fileData(cvFile);await sapi('/api/service-provider/me',{method:'PUT',body:JSON.stringify({display_name:document.getElementById('providerName').value,professional_headline:document.getElementById('providerHeadline').value,about:document.getElementById('providerAbout').value,service_area:document.getElementById('providerArea').value,years_experience:document.getElementById('providerYears').value,languages:document.getElementById('providerLanguages').value,availability_text:document.getElementById('providerAvailability').value,pricing_model:document.getElementById('providerPricing').value,price_from:document.getElementById('providerFrom').value,price_to:document.getElementById('providerTo').value,same_day_available:document.getElementById('providerSameDay').checked,public_reputation_enabled:document.getElementById('providerReputation').checked,visibility:document.getElementById('providerVisibility').value,profile_image_data_url:photo||undefined,cv_file_name:cvFile?.name||undefined,cv_private_data_url:cv||undefined,cv_public_summary:document.getElementById('providerCvSummary').value})});stoast('Service Provider profile saved.');await openProviderWorkspace('Profile')}catch(error){msg.textContent=error.message}};
  }
  if(servicesForm){
    servicesForm.querySelectorAll('[data-service-category]').forEach(checkbox=>{checkbox.onchange=()=>checkbox.closest('[data-service-offer]').querySelector('[data-service-config]').classList.toggle('hidden',!checkbox.checked)});
    servicesForm.querySelectorAll('[data-service-field="pricing_method"]').forEach(method=>{method.onchange=()=>{const unit=method.closest('[data-service-offer]').querySelector('[data-service-field="rate_unit"]');unit.value={fixed:'job',hourly:'hour',half_day:'half_day',daily:'day',per_unit:'unit',per_sqm:'sqm',inspection_then_quote:'visit',quotation:'job'}[method.value]||'job'}});
    servicesForm.onsubmit=async event=>{
      event.preventDefault();
      const msg=document.getElementById('providerServicesMsg'),services=[];
      for(const card of event.currentTarget.querySelectorAll('[data-service-offer]')){
        const checkbox=card.querySelector('[data-service-category]');if(!checkbox.checked)continue;
        const service={category_id:Number(checkbox.dataset.serviceCategory)};
        card.querySelectorAll('[data-service-field]').forEach(field=>service[field.dataset.serviceField]=field.value);
        services.push(service);
      }
      msg.textContent='Saving…';
      try{await sapi('/api/service-provider/services',{method:'PUT',body:JSON.stringify({services})});stoast('Services and pricing updated.');await openProviderWorkspace('Services')}catch(error){msg.textContent=error.message}
    };
  }
  if(addCredential)addCredential.onclick=openCredentialModal;
}
function openCredentialModal(){const m=document.getElementById('serviceModal'),b=document.getElementById('serviceModalBackdrop');m.innerHTML=`<h2>Add qualification / evidence</h2><form id="credentialForm" class="serviceModalForm"><label>Type<select id="credType"><option value="prc_license">PRC professional licence</option><option value="tesda_nc_coc">TESDA NC / COC</option><option value="diploma_vocational">Diploma / vocational certificate</option><option value="training_certificate">Training certificate</option><option value="experience_certificate">Employer / experience certificate</option><option value="other">Other evidence</option></select></label><label>Qualification/title<input id="credTitle" required></label><label>Issuing body<input id="credIssuer"></label><label>Reference/licence number<input id="credRef"></label><div class="merchantStoreForm two"><label>Issue date<input id="credIssue" type="date"></label><label>Expiry date<input id="credExpiry" type="date"></label></div><label>Evidence file<input id="credFile" type="file" accept="application/pdf,image/png,image/jpeg,image/webp"></label><div class="fileNote">A submitted file is not displayed as Verified until Admin verifies it.</div><div id="credMsg" class="fileNote"></div><div class="serviceModalActions"><button class="cancel" type="button">Cancel</button><button class="save">Submit evidence</button></div></form>`;openServiceModal();m.querySelector('.cancel').onclick=closeServiceModal;m.querySelector('#credentialForm').onsubmit=async e=>{e.preventDefault();try{const evidenceFile=document.getElementById('credFile').files?.[0];if(!evidenceFile)throw new Error('Choose an evidence file.');const evidence=await fileData(evidenceFile);await sapi('/api/service-provider/credentials',{method:'POST',body:JSON.stringify({credential_type:document.getElementById('credType').value,title:document.getElementById('credTitle').value,issuing_body:document.getElementById('credIssuer').value,reference_number:document.getElementById('credRef').value,issue_date:document.getElementById('credIssue').value||null,expiry_date:document.getElementById('credExpiry').value||null,evidence_file_name:evidenceFile.name,evidence_data_url:evidence})});closeServiceModal();stoast('Credential submitted for verification.');await openProviderWorkspace('Qualifications')}catch(err){document.getElementById('credMsg').textContent=err.message}}}
function jobPaymentEvidence(j,side){
  const summary=j._payment;
  if(j.status!=='completed'||!j.customer_confirmed_at)return'';
  if(!summary)return '<div class="providerMeta"><span>Payment status unavailable</span></div>';
  const payment=summary.payment||{},settlement=summary.settlement||{},latest=payment.latest_intent||{};
  const paid=Number(payment.effective_paid||0),due=Number(payment.outstanding||0),refunded=Number(payment.refunded||0);
  const receipt=latest.public_id?String(latest.public_id):'';
  const items=[
    '<span>Paid '+sphp(paid)+'</span>',
    '<span>Still due '+sphp(due)+'</span>'
  ];
  if(refunded>0)items.push('<span>Refunded '+sphp(refunded)+'</span>');
  if(receipt&&paid>0)items.push('<span>Receipt '+sh(receipt)+'</span>');
  if(side==='provider')items.push('<span>Settlement '+sh(snice(settlement.status||'not_configured'))+'</span>');
  return '<div class="providerMeta">'+items.join('')+'</div>';
}
async function openServiceJobPayMongo(id){
  const summary=await sapi('/api/payments/service-jobs/'+id+'/summary');
  if(Number(summary?.payment?.outstanding||0)<=0){stoast('Payment is already confirmed.');return openCustomerJobs()}
  let intent=summary?.payment?.pending_amount>0?summary?.payment?.latest_intent:null;
  if(!intent||!['requires_provider','requires_action','processing'].includes(intent.status)){
    const uuid=globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():(Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
    intent=await sapi('/api/payments/intents/service-job/'+id,{
      method:'POST',
      headers:{'Idempotency-Key':'service-job-'+id+'-'+uuid},
      body:JSON.stringify({provider_code:'paymongo',logical_method:'online_other'})
    });
  }
  const checkout=await sapi('/api/payments/paymongo/checkout/'+encodeURIComponent(intent.public_id),{method:'POST',body:'{}'});
  if(checkout.already_paid){stoast('Payment is already confirmed.');return openCustomerJobs()}
  if(!checkout.checkout_url)throw new Error('PayMongo Checkout did not return a payment page.');
  window.location.assign(checkout.checkout_url);
}
async function openExactLocationModal(id){
  const location=await sapi(`/api/service-provider/jobs/${id}/exact-location`),m=document.getElementById('serviceModal');
  m.innerHTML=`<h2>Exact service address</h2><p class="blockSafetyCopy">Use this address only to fulfil this accepted job.</p><div class="providerEditCard"><strong>${sh(location.service_location)}</strong><div class="fileNote">Access is logged and expires when this job is no longer active.</div></div><div class="serviceModalActions"><button class="save" type="button">Close</button></div>`;
  openServiceModal();
  m.querySelector('.save').onclick=closeServiceModal;
}
const QUOTE_ITEM_LABELS={labor:'Labour',materials:'Materials',callout:'Call-out / inspection',travel:'Travel',other:'Other'};
function quoteBreakdown(quote,title){
  if(!quote)return'';
  const lines=Array.isArray(quote.line_items)?quote.line_items:[];
  const expiry=quote.valid_until?new Date(quote.valid_until).toLocaleString():'';
  return `<section class="quoteBreakdown ${quote.quote_phase==='change_order'?'changeOrder':''}">
    <div class="quoteBreakdownHead"><div><small>${sh(title)} · version ${Number(quote.version_no||1)}</small><strong>${sphp(quote.total_amount)}</strong></div><span>${sh(snice(quote.status))}</span></div>
    <p>${sh(quote.scope_summary||'Service work described in the request')}</p>
    <div class="quoteItems">${lines.map(line=>`<div class="quoteItem"><span><strong>${sh(QUOTE_ITEM_LABELS[line.item_kind]||snice(line.item_kind))}</strong><small>${sh(line.description)} · ${Number(line.quantity)} ${sh(SERVICE_UNIT_LABELS[line.unit_code]||line.unit_code)} × ${sphp(line.unit_price)}</small></span><b>${sphp(line.subtotal)}</b></div>`).join('')}</div>
    <div class="quoteTotal"><span>Total accepted if approved</span><strong>${sphp(quote.total_amount)}</strong></div>
    <div class="quoteFacts"><span>${sh(SERVICE_MATERIALS_LABELS[quote.materials_policy]||snice(quote.materials_policy))}</span>${quote.estimated_duration_value?`<span>Estimated ${Number(quote.estimated_duration_value)} ${sh(quote.estimated_duration_unit)}${Number(quote.estimated_duration_value)===1?'':'s'}</span>`:''}${expiry?`<span>Valid until ${sh(expiry)}</span>`:''}</div>
    ${quote.inclusions?`<p><strong>Included:</strong> ${sh(quote.inclusions)}</p>`:''}${quote.exclusions?`<p><strong>Excluded:</strong> ${sh(quote.exclusions)}</p>`:''}${quote.terms?`<p><strong>Terms:</strong> ${sh(quote.terms)}</p>`:''}
  </section>`;
}
function jobPricing(j){const pricing=j.pricing||{},accepted=pricing.accepted_quote,current=pricing.current_quote,pending=pricing.pending_change;return `${accepted?quoteBreakdown(accepted,'Customer-accepted price'):''}${current?quoteBreakdown(current,'Quote awaiting Customer response'):''}${pending?quoteBreakdown(pending,'Change awaiting Customer approval'):''}${!accepted&&!current&&!pending&&j.quote_amount!=null?`<div class="providerMeta"><span>Legacy quote ${sphp(j.quote_amount)}</span></div>`:''}${j.final_price!=null?`<div class="providerMeta"><span>Final agreed price ${sphp(j.final_price)}</span></div>`:''}`}
function quoteActionButton(label,action,j,quote,primary=false){return `<button class="${primary?'primary':''}" data-job-action="${action}" data-job="${j.id}" data-quote-id="${quote?.id||''}" data-quote-version="${quote?.version_no||''}">${label}</button>`}
function jobCard(j,side){
  const other=side==='provider'?j.customer_name:j.provider_name,pricing=j.pricing||{},current=pricing.current_quote,pending=pricing.pending_change,accepted=pricing.accepted_quote;
  let actions='';const payment=j._payment?.payment||null;
  if(side==='provider'){
    if(['requested','provider_reviewing','quoted'].includes(j.status))actions+=quoteActionButton(current?'Revise itemised quote':'Build itemised quote','quote',j,current,true);
    if(j.status==='requested')actions+=quoteActionButton('Reviewing','reviewing',j,null);
    if(['accepted','scheduled','in_progress'].includes(j.status))actions+=quoteActionButton(pending?'Replace pending change':'Change price / scope','change_order',j,accepted);
    if(j.exact_location_available)actions+=quoteActionButton('View exact service address','view_location',j,null);
    if(['accepted','scheduled'].includes(j.status))actions+=quoteActionButton('Start job','in_progress',j,null,true);
    if(j.status==='in_progress'&&!pending)actions+=quoteActionButton(`Complete at ${sphp(j.agreed_total??accepted?.total_amount)}`,'completed',j,accepted,true);
    if(j.status==='in_progress'&&pending)actions+='<button type="button" disabled>Awaiting change decision</button>';
  }else{
    if(current){actions+=quoteActionButton(`Accept quote ${sphp(current.total_amount)}`,'accept',j,current,true);actions+=quoteActionButton('Request changes','request_quote_changes',j,current);actions+=quoteActionButton('Decline quote','decline_quote',j,current)}
    if(pending){actions+=quoteActionButton(`Accept change ${sphp(pending.total_amount)}`,'accept_change',j,pending,true);actions+=quoteActionButton('Request changes','request_change_changes',j,pending);actions+=quoteActionButton('Decline change','decline_change',j,pending)}
    if(j.status==='completed'&&!j.customer_confirmed_at)actions+=quoteActionButton('Confirm completed','confirm',j,accepted,true);
    if(j.status==='completed'&&j.customer_confirmed_at&&payment&&Number(payment.outstanding||0)>0)actions+=`<button class="primary" data-job-action="pay" data-job="${j.id}">Pay ${sphp(payment.outstanding)}</button>`;
    if(j.status==='completed'&&j.customer_confirmed_at&&payment&&Number(payment.outstanding||0)<=0)actions+='<button type="button" disabled>Payment received</button>';
    if(j.status==='completed'&&j.customer_confirmed_at)actions+=quoteActionButton('Leave review','review',j,null);
  }
  const location=side==='provider'?`<div class="providerMeta"><span>Area: ${sh(j.coarse_location||'Area not recorded')}</span><span>${j.exact_location_available?'Exact address available for active fulfilment':'Exact address private'}</span></div>`:`<div class="providerMeta"><span>Area shared: ${sh(j.coarse_location||'Area not recorded')}</span>${j.service_location?`<span>Your service address: ${sh(j.service_location)}</span>`:''}</div>`;
  return `<article class="jobCard"><div class="jobCardTop"><strong>${sh(j.category||j.service_label||'Service job')} • ${sh(other||'')}</strong><span class="jobStatus">${sh(snice(j.status))}</span></div><p>${sh(j.description)}</p>${location}${jobPricing(j)}${jobPaymentEvidence(j,side)}<div class="jobActions">${actions}</div></article>`;
}
function bindJobActions(side){svcWorkspace.querySelectorAll('[data-job-action]').forEach(button=>button.onclick=()=>jobAction(side,button.dataset.jobAction,Number(button.dataset.job),{quoteId:Number(button.dataset.quoteId)||null,version:Number(button.dataset.quoteVersion)||null}))}
async function refreshServiceJobs(side){if(side==='provider')await openProviderWorkspace(svcProviderSection);else await openCustomerJobs()}
function openQuoteResponseModal({side,id,quoteId,version,action,title}){
  const m=document.getElementById('serviceModal');
  m.innerHTML=`<h2>${sh(title)}</h2><form id="quoteResponseForm" class="serviceModalForm"><p class="serviceGuideNotice">Your response is attached to this exact quote version.</p><label>Note to provider<textarea id="quoteResponseNote" rows="3" maxlength="500" placeholder="Explain the requested change or reason"></textarea></label><div id="quoteResponseMsg" class="fileNote"></div><div class="serviceModalActions"><button class="cancel" type="button">Cancel</button><button class="save">Send response</button></div></form>`;
  openServiceModal();m.querySelector('.cancel').onclick=closeServiceModal;
  m.querySelector('#quoteResponseForm').onsubmit=async event=>{event.preventDefault();try{await sapi(`/api/services/jobs/${id}/quotes/${quoteId}/respond`,{method:'POST',body:JSON.stringify({action,expected_version:version,note:m.querySelector('#quoteResponseNote').value})});closeServiceModal();stoast('Quote response sent.');await refreshServiceJobs(side)}catch(error){m.querySelector('#quoteResponseMsg').textContent=error.message}};
}
async function jobAction(side,action,id,meta={}){
  try{
    if(action==='quote')return openQuoteModal(id,'initial');
    if(action==='change_order')return openQuoteModal(id,'change_order');
    if(action==='pay')return openServiceJobPayMongo(id);
    if(action==='view_location')return openExactLocationModal(id);
    if(action==='review')return openReviewModal(id);
    if(action==='request_quote_changes')return openQuoteResponseModal({side,id,quoteId:meta.quoteId,version:meta.version,action:'request_changes',title:'Request quote changes'});
    if(action==='request_change_changes')return openQuoteResponseModal({side,id,quoteId:meta.quoteId,version:meta.version,action:'request_changes',title:'Request change-order edits'});
    if(action==='decline_quote')return openQuoteResponseModal({side,id,quoteId:meta.quoteId,version:meta.version,action:'decline',title:'Decline quote'});
    if(action==='decline_change')return openQuoteResponseModal({side,id,quoteId:meta.quoteId,version:meta.version,action:'decline',title:'Decline change'});
    if(action==='accept')await sapi(`/api/services/jobs/${id}/accept-quote`,{method:'POST',body:JSON.stringify({quote_id:meta.quoteId,expected_version:meta.version})});
    else if(action==='accept_change')await sapi(`/api/services/jobs/${id}/quotes/${meta.quoteId}/respond`,{method:'POST',body:JSON.stringify({action:'accept',expected_version:meta.version})});
    else if(action==='confirm')await sapi(`/api/services/jobs/${id}/confirm-completion`,{method:'POST',body:'{}'});
    else if(side==='provider'){const status=action==='reviewing'?'provider_reviewing':action;await sapi(`/api/service-provider/jobs/${id}/status`,{method:'POST',body:JSON.stringify({status})})}
    stoast(action==='accept_change'?'Approved change is now the agreed price.':'Service job updated.');await refreshServiceJobs(side);
  }catch(error){stoast(error.message)}
}
function datetimeLocalValue(value){const date=value?new Date(value):new Date(Date.now()+7*24*60*60*1000);return Number.isNaN(date.getTime())?'':new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function quoteLineRow(line={}){const kind=line.item_kind||'labor',unit=line.unit_code||'job';return `<div class="quoteLineEditor" data-quote-line><label>Type<select data-line-field="item_kind">${selectOptions(QUOTE_ITEM_LABELS,kind)}</select></label><label class="quoteLineDescription">Description<input data-line-field="description" value="${sh(line.description||'')}" maxlength="240" required placeholder="Work or material"></label><label>Quantity<input data-line-field="quantity" type="number" min="0.001" step="0.001" value="${line.quantity??1}" required></label><label>Unit<select data-line-field="unit_code">${selectOptions(SERVICE_UNIT_LABELS,unit)}</select></label><label>Unit price ₱<input data-line-field="unit_price" type="number" min="0" step="0.01" value="${line.unit_price??''}" required></label><div class="quoteLineSubtotal"><span>Subtotal</span><strong data-line-subtotal>${sphp((Number(line.quantity)||0)*(Number(line.unit_price)||0))}</strong></div><button type="button" data-remove-quote-line aria-label="Remove item">Remove</button></div>`}
function updateQuoteTotal(modal){let total=0;modal.querySelectorAll('[data-quote-line]').forEach(row=>{const quantity=Number(row.querySelector('[data-line-field="quantity"]').value)||0,price=Number(row.querySelector('[data-line-field="unit_price"]').value)||0,subtotal=Math.round(quantity*price*100)/100;row.querySelector('[data-line-subtotal]').textContent=sphp(subtotal);total+=subtotal});modal.querySelector('[data-quote-total]').textContent=sphp(Math.round(total*100)/100)}
function bindQuoteEditor(modal){const host=modal.querySelector('#quoteLines');const bindRow=row=>{row.querySelectorAll('input,select').forEach(field=>field.addEventListener('input',()=>updateQuoteTotal(modal)));row.querySelector('[data-remove-quote-line]').onclick=()=>{if(host.querySelectorAll('[data-quote-line]').length===1)return;row.remove();updateQuoteTotal(modal)}};host.querySelectorAll('[data-quote-line]').forEach(bindRow);modal.querySelector('#addQuoteLine').onclick=()=>{host.insertAdjacentHTML('beforeend',quoteLineRow());bindRow(host.lastElementChild);updateQuoteTotal(modal)};updateQuoteTotal(modal)}
async function openQuoteModal(id,phase='initial'){
  const m=document.getElementById('serviceModal');let base=null;
  if(phase==='change_order'){const pricing=await sapi(`/api/services/jobs/${id}/pricing`);base=pricing.quotes.find(quote=>Number(quote.id)===Number(pricing.accepted_quote_id))||pricing.quotes.filter(quote=>quote.status==='accepted').at(-1)||null}
  const lines=base?.line_items?.length?base.line_items:[{item_kind:'labor',description:'',quantity:1,unit_code:'job',unit_price:''}],change=phase==='change_order';
  m.innerHTML=`<h2>${change?'Create change order':'Build itemised quote'}</h2><form id="quoteForm" class="serviceModalForm"><p class="serviceGuideNotice">${change?'Enter the complete revised scope and full new total. The current accepted price remains binding until the Customer accepts this change.':'Break out labour, materials and visit charges. The Customer accepts this exact version and total.'}</p>${change?'':`<label>Quote type<select id="quoteKind"><option value="fixed_quote">Fixed quote</option><option value="estimate">Estimate with stated assumptions</option><option value="inspection">Inspection / diagnostic visit</option></select></label>`}<label>Scope summary<textarea id="quoteScope" rows="3" maxlength="1200" required placeholder="Describe the work covered">${sh(base?.scope_summary||'')}</textarea></label><div class="quoteEditorHeading"><strong>Price items</strong><button id="addQuoteLine" type="button">+ Add item</button></div><div id="quoteLines" class="quoteLineList">${lines.map(quoteLineRow).join('')}</div><div class="quoteEditorTotal"><span>Server-calculated total</span><strong data-quote-total>${sphp(0)}</strong></div><div class="serviceFormGrid"><label>Materials<select id="quoteMaterials">${selectOptions(SERVICE_MATERIALS_LABELS,base?.materials_policy||'separate')}</select></label><label>Valid until<input id="quoteValidUntil" type="datetime-local" value="${datetimeLocalValue()}" required></label></div><div class="serviceFormGrid"><label>Estimated duration<input id="quoteDuration" type="number" min="0.01" step="0.01" value="${base?.estimated_duration_value??''}" placeholder="Optional"></label><label>Duration unit<select id="quoteDurationUnit"><option value="hour" ${base?.estimated_duration_unit==='hour'?'selected':''}>Hours</option><option value="day" ${base?.estimated_duration_unit==='day'?'selected':''}>Days</option></select></label></div><label>Included<textarea id="quoteInclusions" rows="2" maxlength="1200">${sh(base?.inclusions||'')}</textarea></label><label>Excluded<textarea id="quoteExclusions" rows="2" maxlength="1200">${sh(base?.exclusions||'')}</textarea></label><label>Terms / assumptions<textarea id="quoteTerms" rows="2" maxlength="1200">${sh(base?.terms||'')}</textarea></label><div id="quoteMsg" class="fileNote"></div><div class="serviceModalActions"><button class="cancel" type="button">Cancel</button><button class="save">${change?'Send change for approval':'Send quote'}</button></div></form>`;
  openServiceModal();m.querySelector('.cancel').onclick=closeServiceModal;bindQuoteEditor(m);
  m.querySelector('#quoteForm').onsubmit=async event=>{event.preventDefault();const lineItems=[...m.querySelectorAll('[data-quote-line]')].map(row=>{const value=name=>row.querySelector(`[data-line-field="${name}"]`).value;return{item_kind:value('item_kind'),description:value('description'),quantity:value('quantity'),unit_code:value('unit_code'),unit_price:value('unit_price')}});const duration=m.querySelector('#quoteDuration').value;const payload={quote_kind:change?'change_order':m.querySelector('#quoteKind').value,scope_summary:m.querySelector('#quoteScope').value,materials_policy:m.querySelector('#quoteMaterials').value,estimated_duration_value:duration||null,estimated_duration_unit:duration?m.querySelector('#quoteDurationUnit').value:null,valid_until:new Date(m.querySelector('#quoteValidUntil').value).toISOString(),inclusions:m.querySelector('#quoteInclusions').value,exclusions:m.querySelector('#quoteExclusions').value,terms:m.querySelector('#quoteTerms').value,line_items:lineItems};try{await sapi(`/api/service-provider/jobs/${id}/quotes`,{method:'POST',body:JSON.stringify(payload)});closeServiceModal();stoast(change?'Change sent for Customer approval.':'Itemised quote sent.');await openProviderWorkspace(change?'Jobs':'Quotes')}catch(error){m.querySelector('#quoteMsg').textContent=error.message}};
}
function openReviewModal(id){const m=document.getElementById('serviceModal'),b=document.getElementById('serviceModalBackdrop');m.innerHTML=`<h2>Verified service review</h2><form id="reviewForm" class="serviceModalForm">${['workmanship','reliability','communication','professionalism','property_care','price_transparency','overall'].map(k=>`<label>${sh(snice(k))}<select data-rating="${k}"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Fair</option><option value="2">2 — Poor</option><option value="1">1 — Very poor</option></select></label>`).join('')}<label>Feedback<textarea id="reviewText" rows="3"></textarea></label><div id="reviewMsg" class="fileNote"></div><div class="serviceModalActions"><button class="cancel" type="button">Cancel</button><button class="save">Submit review</button></div></form>`;openServiceModal();m.querySelector('.cancel').onclick=closeServiceModal;m.querySelector('#reviewForm').onsubmit=async e=>{e.preventDefault();const payload={review_text:document.getElementById('reviewText').value};e.currentTarget.querySelectorAll('[data-rating]').forEach(x=>payload[x.dataset.rating]=Number(x.value));try{await sapi(`/api/services/jobs/${id}/review`,{method:'POST',body:JSON.stringify(payload)});closeServiceModal();stoast('Verified review submitted.');await openCustomerJobs()}catch(err){document.getElementById('reviewMsg').textContent=err.message}}}

function applySvcState(detail){const state=detail?.snapshot?detail:window.BusinessLifeProfileState;if(state?.snapshot)svcMe=state.snapshot}
async function decorateSvc(detail){if(!ensureSvc()||!stok())return;const state=detail?.snapshot?detail:window.BusinessLifeProfileState;applySvcState(state);if(!svcMe)return;const role=state?.surface==='profile'?state.activeRole:null,hub=document.getElementById('roleHub');if(hub&&role==='customer'){const local=hub.querySelector('[data-hub-feature="Local Services"]');if(local)local.onclick=()=>openDirectory('')}if(hub&&role==='service_provider'){hub.querySelectorAll('[data-service-provider-section]').forEach(b=>b.onclick=()=>openProviderWorkspace(b.dataset.serviceProviderSection))}}
function observeSvc(){document.addEventListener('abl:profile-state',e=>decorateSvc(e.detail).catch(()=>{}),{passive:true})}
window.BusinessLifeServices=Object.freeze({openDirectory,openCustomerJobs,openProviderWorkspace});
async function boot(){ensureSvc();observeSvc();await decorateSvc(window.BusinessLifeProfileState)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
